import { linter } from '@codemirror/lint';
import { useIntl } from 'react-intl';

import { generateErrorsOrDiagnostics } from '../utils/generate-errors-or-diagnostics.js';

export function useFilterFieldLinting() {
  const intl = useIntl();
  const emptyGroupError = intl.formatMessage({
    defaultMessage: 'A group cannot be empty.',
    id: 'U4LTHt7BSgC51Yri',
    description: 'Filter field empty group error',
  });
  const incompleteGroupError = intl.formatMessage({
    defaultMessage: 'A group seems to be missing a closing bracket.',
    id: 'b/iZ9wZnx4JoohNn',
    description: 'Filter field incomplete group error',
  });
  const incompleteStatementError = intl.formatMessage({
    defaultMessage: 'The filter field statement is incomplete.',
    id: 'jtrx2KCeXnLeA8Kd',
    description: 'Filter field incomplete statement error',
  });
  const missingKeyError = intl.formatMessage({
    defaultMessage: 'The filter key is missing.',
    id: '1yn5LJXBZlEagfkL',
    description: 'Filter field missing key error',
  });
  const missingValueError = intl.formatMessage({
    defaultMessage: 'The filter value is missing.',
    id: 'kctf0+Hea33LxYTL',
    description: 'Filter field missing value error',
  });
  const missingOperatorError = intl.formatMessage({
    defaultMessage: 'Missing operator.',
    id: 'ABXa8Ni5H9+ZO7E0',
    description: 'Filter field missing operator',
  });
  const invalidOperatorError = intl.formatMessage({
    defaultMessage:
      'Invalid operator. The only operators allowed are: =, !=, >, >=, <, <=, in, !in.',
    id: 'c1quZIu7ENW3cNZu',
    description: 'Filter field invalid operator',
  });
  const invalidValueError = intl.formatMessage({
    defaultMessage: 'The filter value is invalid.',
    id: 'FNr7Qz7K7FFouhDD',
    description: 'Filter field invalid value error',
  });
  const incompleteRangeError = intl.formatMessage({
    defaultMessage: 'The entered range is incomplete.',
    id: '+xSFSJOLYctgJ5Ab',
    description: 'Filter field incomplete range error',
  });
  const incompleteListError = intl.formatMessage({
    defaultMessage: 'The entered list is incomplete.',
    id: 'cbCymkDqnaJqnDu0',
    description: 'Filter field incomplete range error',
  });
  const invalidLogicalOperator = intl.formatMessage({
    defaultMessage: 'A logical operator cannot occur in this position.',
    id: '5Byu0D+YGc1DoTBc',
    description: 'Filter field invalid logical operator',
  });

  const filterFieldLinter = linter((view) =>
    generateErrorsOrDiagnostics(view, {
      emptyGroupError,
      incompleteGroupError,
      incompleteStatementError,
      missingKeyError,
      missingValueError,
      missingOperatorError,
      invalidOperatorError,
      invalidValueError,
      incompleteRangeError,
      incompleteListError,
      invalidLogicalOperator,
    }),
  );

  return filterFieldLinter;
}
